CREATE TABLE IF NOT EXISTS `#__joomleague_standing_adjustment` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `uuid` CHAR(36) NOT NULL, `project_id` BIGINT UNSIGNED NOT NULL, `stage_id` BIGINT UNSIGNED NULL DEFAULT NULL, `stage_key` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `project_entry_id` BIGINT UNSIGNED NOT NULL, `scope_code` VARCHAR(100) NOT NULL DEFAULT 'all', `metric_code` VARCHAR(100) NOT NULL, `adjustment_value` DECIMAL(30,9) NOT NULL, `reason` VARCHAR(500) NOT NULL, `effective_date` DATE NULL DEFAULT NULL,
  `published` TINYINT NOT NULL DEFAULT 1, `ordering` INT NOT NULL DEFAULT 0, `created` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `created_by` BIGINT UNSIGNED NOT NULL DEFAULT 0, `modified` DATETIME NULL DEFAULT NULL, `modified_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`), UNIQUE KEY `uq_jl_standing_adjustment_uuid` (`uuid`), KEY `idx_jl_standing_adjustment_context` (`project_id`, `stage_key`, `scope_code`, `published`, `ordering`), KEY `idx_jl_standing_adjustment_entry` (`project_entry_id`),
  CONSTRAINT `fk_jl_standing_adjustment_project` FOREIGN KEY (`project_id`) REFERENCES `#__joomleague_project` (`id`) ON DELETE CASCADE, CONSTRAINT `fk_jl_standing_adjustment_stage` FOREIGN KEY (`stage_id`, `project_id`) REFERENCES `#__joomleague_project_stage` (`id`, `project_id`) ON DELETE CASCADE, CONSTRAINT `fk_jl_standing_adjustment_entry` FOREIGN KEY (`project_entry_id`, `project_id`) REFERENCES `#__joomleague_project_entry` (`id`, `project_id`) ON DELETE CASCADE,
  CONSTRAINT `chk_jl_standing_adjustment_stage` CHECK ((`stage_id` IS NULL AND `stage_key` = 0) OR (`stage_id` IS NOT NULL AND `stage_key` = `stage_id`)), CONSTRAINT `chk_jl_standing_adjustment_scope` CHECK (`scope_code` REGEXP '^[a-z][a-z0-9_]*$'), CONSTRAINT `chk_jl_standing_adjustment_metric` CHECK (`metric_code` REGEXP '^[a-z][a-z0-9_]*$'), CONSTRAINT `chk_jl_standing_adjustment_value` CHECK (`adjustment_value` <> 0), CONSTRAINT `chk_jl_standing_adjustment_published` CHECK (`published` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
